fn numpy_greater_equal(x1: Vec<i8>, x2: Vec<i8>) -> Vec<bool> {
    // Since we assume x1.len() == x2.len(), we can just zip them.
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a >= b)
      .collect()
}

